pub fn clear_assets() {
    let cache_dir_buf: PathBuf = if let Some(bat_cache_path) = env::var_os("BAT_CACHE_PATH") {
        PathBuf::from(bat_cache_path)
    } else {
        #[cfg(target_os = "macos")]
        {
            let macos_cache = if let Some(xdg_cache_home) = env::var_os("XDG_CACHE_HOME") {
                let xdg_path = PathBuf::from(xdg_cache_home);
                if xdg_path.is_absolute() {
                    Some(xdg_path)
                } else {
                    dirs_next::home_dir().map(|home_dir| home_dir.join(".cache"))
                }
            } else {
                dirs_next::home_dir().map(|home_dir| home_dir.join(".cache"))
            };
            if let Some(path) = macos_cache {
                path.join("bat")
            } else {
                PROJECT_DIRS.cache_dir().to_path_buf()
            }
        }
        #[cfg(not(target_os = "macos"))]
        {
            if let Some(path) = dirs_next::cache_dir() {
                path.join("bat")
            } else {
                PROJECT_DIRS.cache_dir().to_path_buf()
            }
        }
    };
    let cache_dir: &Path = cache_dir_buf.as_path();

    let themes_filename = "themes.bin";
    let syntaxes_filename = "syntaxes.bin";
    let metadata_filename = "metadata.yaml";
    let themes_description = "theme set cache";
    let syntaxes_description = "syntax set cache";
    let metadata_description = "metadata file";
    let themes_path_default = cache_dir.join(themes_filename);
    let syntaxes_path_default = cache_dir.join(syntaxes_filename);
    let metadata_path_default = cache_dir.join(metadata_filename);

    let mut existing_names: Vec<String> = Vec::new();
    let mut existing_files: Vec<PathBuf> = Vec::new();
    let mut readable_dir = false;
    if let Ok(entries) = fs::read_dir(cache_dir) {
        readable_dir = true;
        for entry in entries.flatten() {
            existing_files.push(entry.path());
            existing_names.push(entry.file_name().to_string_lossy().into_owned());
        }
    }

    existing_names.sort();
    existing_files.sort();
    let existing_count = existing_files.len();
    let has_themes = existing_names.iter().any(|name| name == themes_filename);
    let has_syntaxes = existing_names.iter().any(|name| name == syntaxes_filename);
    let has_metadata_file = existing_names.iter().any(|name| name == metadata_filename);
    let listed_cache_assets = has_themes || has_syntaxes || has_metadata_file;

    let mut loaded_metadata: Option<AssetsMetadata> = None;
    let mut cache_state = "unknown";
    if let Ok(dir_meta) = fs::metadata(cache_dir) {
        if dir_meta.is_dir() {
            readable_dir = true;
            match AssetsMetadata::load_from_folder(cache_dir) {
                Ok(Some(metadata)) => {
                    if metadata.is_compatible_with(crate_version!()) {
                        cache_state = "compatible";
                        let cached_assets = HighlightingAssets::from_cache(cache_dir);
                        if cached_assets.is_ok() {
                            cache_state = "compatible";
                        } else {
                            cache_state = "compatible-unreadable";
                        }
                        loaded_metadata = Some(metadata);
                    } else {
                        cache_state = "incompatible";
                        loaded_metadata = Some(metadata);
                    }
                }
                Ok(None) => {
                    cache_state = "absent";
                }
                Err(error) => match error {
                    Error::SerdeYamlError(_) => {
                        cache_state = "invalid-yaml";
                    }
                    Error::Io(_) => {
                        cache_state = "io-error";
                    }
                    _ => {
                        cache_state = "other-error";
                    }
                },
            }
        } else {
            cache_state = "not-a-directory";
        }
    } else {
        cache_state = "missing-dir";
    }

    let reconstruct_path = if let Some(metadata) = loaded_metadata.as_ref() {
        metadata.is_compatible_with(crate_version!()) && cache_state == "compatible"
    } else {
        readable_dir && listed_cache_assets && existing_count > 0
    };

    let mut asset_specs: Vec<(&str, &str, PathBuf)> = Vec::new();
    asset_specs.push((
        themes_filename,
        themes_description,
        themes_path_default.clone(),
    ));
    asset_specs.push((
        syntaxes_filename,
        syntaxes_description,
        syntaxes_path_default.clone(),
    ));
    asset_specs.push((
        metadata_filename,
        metadata_description,
        metadata_path_default.clone(),
    ));

    for (filename, description, default_path) in asset_specs.iter() {
        print!("Clearing {} ... ", description);

        let mut path = PathBuf::new();
        let mut reconstructed = false;
        if reconstruct_path {
            if let Some(parent) = cache_dir.parent() {
                if parent.exists() || cache_dir.exists() {
                    for component in cache_dir.components() {
                        path.push(component);
                        if path.as_path() == cache_dir {
                            reconstructed = true;
                            break;
                        }
                    }
                }
            }
        }

        if reconstructed {
            path.push(filename);
        } else {
            path = default_path.clone();
        }

        match fs::remove_file(&path) {
            Err(err) if err.kind() == io::ErrorKind::NotFound => {
                println!("skipped (not present)");
            }
            Err(err) => {
                println!("could not remove the cache file {:?}: {}", &path, err);
            }
            Ok(_) => println!("okay"),
        }
    }
}

pub fn assets_from_cache_or_binary(use_custom_assets: bool) -> Result<HighlightingAssets> {
    let cache_dir = PROJECT_DIRS.cache_dir();
    if let Some(metadata) = AssetsMetadata::load_from_folder(cache_dir)? {
        if !metadata.is_compatible_with(crate_version!()) {
            return Err(format!(
                "The binary caches for the user-customized syntaxes and themes \
                 in '{}' are not compatible with this version of bat ({}). To solve this, \
                 either rebuild the cache (bat cache --build) or remove \
                 the custom syntaxes/themes (bat cache --clear).\n\
                 For more information, see:\n\n  \
                 https://github.com/sharkdp/bat#adding-new-syntaxes--language-definitions",
                cache_dir.to_string_lossy(),
                crate_version!()
            )
            .into());
        }
    }

    let custom_assets = if use_custom_assets {
        HighlightingAssets::from_cache(cache_dir).ok()
    } else {
        None
    };
    Ok(custom_assets.unwrap_or_else(HighlightingAssets::from_binary))
}

